package com.example.spring_blog.board;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.DeleteMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.RestController;@RestController@RequiredArgsConstructorpublic class BoardApiController {    private final BoardPersistRepository boardPersistRepository;    @DeleteMapping("/api/boards/{id}")    public ResponseEntity<String> delete(@PathVariable Long id) {        try {            boardPersistRepository.deleteById(id);            return ResponseEntity.ok("삭제됨");        }catch (Exception e) {            return ResponseEntity.badRequest().body(e.getMessage());        }    }}